const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
const e=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const date=v=>v?new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'Ещё не проверено';
const dateOnly=v=>v?new Intl.DateTimeFormat('ru-RU',{dateStyle:'medium'}).format(new Date(v)):'—';
const checked=b=>b?'checked':'';
const selected=(a,b)=>a===b?'selected':'';
const external=(url,label,cls='')=>`<a class="${cls}" href="${e(url)}" target="_blank" rel="noopener noreferrer" ${cls==='icon-btn'?'aria-label="Открыть карточку компании в 2ГИС"':''}>${label}</a>`;
const tag=(text,cls='')=>`<span class="tag ${cls}">${e(text)}</span>`;
const button=(action,label,ico,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const tiny=(action,title,ico,id='')=>`<button class="icon-btn" type="button" title="${e(title)}" aria-label="${e(title)}" data-action="${action}" data-id="${e(id)}">${icon(ico)}</button>`;
const byId=id=>document.getElementById(id);
const modal=byId('modal');
let state,route='companies',modalType='',activeRunId=null,polling=false;
let filters={q:'',website_status:'',lead_status:'',review_status:'',city:'',category:'',sort:'priority',phone:false,exclude_chains:false};
let searchDraft={city:'',district:'',categories:['Кафе','Салоны красоты','Автосервисы'],queries:[],limit:30,exclude_chains:true,mode:'manual'};
let currentEditor=null,currentRunAgent=null,moreFilters=false;

async function api(path,method='GET',data){
  const res=await fetch(path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Local-Token':state?.token||''},...(data===undefined?{}:{body:JSON.stringify(data)})});
  const out=await res.json();if(!res.ok)throw Error(out.error||'Не удалось выполнить действие.');return out;
}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;byId('toasts').append(el);setTimeout(()=>el.remove(),error?10000:5500);}
async function refresh(draw=true){state=await api('/api/state');if(draw)render();updateCounts();}
function updateCounts(){document.querySelectorAll('[data-count="leads"]').forEach(n=>n.textContent=state.leads.length);document.querySelectorAll('[data-count="agents"]').forEach(n=>n.textContent=state.agents.length);}
function shell(){
  const nav=[['companies','building','Компании','leads'],['agents','bot','Мои агенты','agents'],['runs','clock','История запусков'],['templates','layers','Шаблоны']];
  byId('app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#companies" aria-label="Контур — главная"><svg class="brand-mark" viewBox="0 0 40 40" aria-hidden="true"><path d="M7 21a13 13 0 1 1 13 13M13 21a7 7 0 1 1 7 7" fill="none" stroke="#d4e9b5" stroke-width="3.1" stroke-linecap="round"/><circle cx="20" cy="21" r="2" fill="#d4e9b5"/></svg><span class="brand-text">контур</span></a><p class="brand-sub">Студия ваших агентов</p><div class="workspace-switch">${icon('grid')}<span>Моё пространство</span>${icon('down')}</div><p class="tiny-label">Рабочее пространство</p><nav class="nav" aria-label="Основная навигация">${nav.map(([r,i,t,c])=>`<a href="#${r}" data-nav="${r}" title="${t}">${icon(i)}<span class="nav-text">${t}</span>${c?`<span class="count" data-count="${c}"></span>`:''}</a>`).join('')}<div class="nav-spacer"></div><a href="#sources" data-nav="sources" title="Источники и файлы">${icon('database')}<span class="nav-text">Источники и файлы</span></a><a href="#settings" data-nav="settings" title="Настройки">${icon('settings')}<span class="nav-text">Настройки</span></a></nav><div class="sidebar-bottom"><div class="local-panel"><strong><span class="dot"></span> Всё под вашим контролем</strong><p>Данные — на компьютере.<br>Каждый запуск — по вашей команде.</p></div><div class="profile"><div class="avatar">МП</div><div>Моё пространство<small>Локальная версия · 1.0</small></div></div></div></aside><div class="main-column"><header class="topbar"><div class="breadcrumbs"><span>Рабочее пространство</span>${icon('chevron')}<b id="breadcrumb">Компании</b></div><div class="topbar-right"><span class="local-badge"><span class="dot"></span> Локально</span><span class="date">${dateOnly(new Date().toISOString())}</span><a class="icon-btn" href="#settings" aria-label="Помощь и настройки">${icon('help')}</a></div></header><main class="content" id="main" tabindex="-1"></main></div></div>`;
}
function heading(eyebrow,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function foot(){return `<footer class="page-foot"><span>${icon('lock')} Ваши данные хранятся на этом компьютере</span><span>Контур · Работайте в своём темпе</span></footer>`;}
function render(){
  route=location.hash.slice(1)||'companies';if(!['companies','agents','runs','templates','sources','settings'].includes(route))route='companies';
  document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===route);if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  byId('breadcrumb').textContent={companies:'Компании',agents:'Мои агенты',runs:'История запусков',templates:'Шаблоны',sources:'Источники и файлы',settings:'Настройки'}[route];
  document.title=`${byId('breadcrumb').textContent} · Контур`;
  byId('main').innerHTML=({companies:companiesPage,agents:agentsPage,runs:runsPage,templates:templatesPage,sources:sourcesPage,settings:settingsPage})[route]()+foot();
  updateCounts();
  if(route==='companies')renderResults();
}
function stat(label,val,meta,ico,cls=''){return `<div class="stat ${cls}"><div class="stat-label">${icon(ico)}${label}</div><div class="stat-value">${val}</div><div class="stat-meta">${meta}</div></div>`;}
function companiesPage(){
  const leads=state.leads,found=leads.filter(l=>l.website_status==='not_found').length,ready=leads.filter(l=>l.lead_status==='Готов к звонку').length,manual=leads.filter(l=>l.website_status==='manual'&&l.review_status!=='unsuitable').length;
  return heading('ОТ ПОИСКА К ПЕРВОМУ РАЗГОВОРУ','Найдите бизнес. Начните разговор.','Соберите компании, проверьте их сайты и подготовьте список для звонков.',button('import','Импортировать','upload')+button('lead-new','Добавить компанию','plus','primary'))+
    `<section class="stats" aria-label="Статистика компаний">${stat('Всего компаний',leads.length,'В вашей локальной базе','building')}${stat('Сайт не найден',found,'После проверки двух источников','globe','featured')}${stat('Нужно проверить',manual,'Сохраняем неопределённость','search')}${stat('Готовы к звонку',ready,'Следующий шаг — за вами','phone')}</section>
    <div class="two-column"><section class="card"><header class="card-head"><div class="card-title"><div class="square-icon">${icon('search')}</div><div><h2>Поиск компаний</h2><p>Встроенный агент · источник 2ГИС</p></div></div>${tag('Ручной запуск','neutral')}</header><form id="search-form" class="search-body"><div class="mode-line"><div class="segmented" aria-label="Режим поиска"><button type="button" class="${searchDraft.mode==='manual'?'active':''}" data-action="search-mode" data-mode="manual">Ручной помощник</button><button type="button" class="${searchDraft.mode==='api'?'active':''}" data-action="search-mode" data-mode="api">Через API 2ГИС</button></div><span class="source-note">${icon('shield')} Проверяемые источники</span></div>${searchDraft.mode==='api'&&!state.config.dgis_ready?`<div class="notice">${icon('info')}<span>Для автопоиска нужны ключ и разрешение 2ГИС на хранение базы. <a href="#settings">Как подключить</a></span></div>`:''}<div class="form-grid"><div class="field"><label for="search-city">Город <span class="optional">· обязательно</span></label><div class="input-wrap">${icon('pin')}<input id="search-city" name="city" value="${e(searchDraft.city)}" placeholder="Например, Самара" required maxlength="200" autocomplete="address-level2"></div></div><div class="field"><label for="search-district">Район <span class="optional">· необязательно</span></label><div class="input-wrap">${icon('pin')}<input id="search-district" name="district" value="${e(searchDraft.district)}" placeholder="Весь город" maxlength="200"></div></div><div class="field full"><label for="search-categories">Категории бизнеса</label><input id="search-categories" name="categories" value="${e(searchDraft.categories.join(', '))}" placeholder="Кафе, салоны красоты, автосервисы" maxlength="1200"><div class="chips">${['Кафе','Салоны красоты','Автосервисы','Цветы','Пекарни'].map(c=>`<button class="chip ${searchDraft.categories.includes(c)?'selected':''}" type="button" data-action="category-chip" data-category="${c}">${icon(searchDraft.categories.includes(c)?'check':'plus')}${c}</button>`).join('')}</div></div><div class="field"><label for="search-queries">Дополнительные запросы <span class="optional">· через запятую</span></label><div class="input-wrap">${icon('search')}<input id="search-queries" name="queries" value="${e(searchDraft.queries.join(', '))}" placeholder="Например, ремонт обуви" maxlength="1500"></div></div><div class="field"><label for="search-limit">Количество результатов</label><select id="search-limit" name="limit">${[10,20,30,50,100].map(v=>`<option value="${v}" ${selected(Number(searchDraft.limit),v)}>До ${v} компаний</option>`).join('')}</select></div></div><div class="search-bottom"><label class="check"><input type="checkbox" name="exclude_chains" ${checked(searchDraft.exclude_chains)}>Исключать крупные сети ${icon('info')}</label><button class="btn primary" type="submit">${icon(searchDraft.mode==='api'?'search':'arrow')}${searchDraft.mode==='api'?'Найти компании':'Подготовить поиск'}</button></div></form></section><aside><section class="aside-card"><div class="eyebrow">Сначала факты, потом звонок</div><h3>Хороший список начинается с проверки</h3><p>Пустое поле «Сайт» в 2ГИС ещё не означает, что у бизнеса его нет.</p><div class="step-list"><div class="step"><span class="step-number">1</span><div><b>Найдите компании</b><p>Выберите город и ниши.<br>Работайте с разрешёнными данными.</p></div></div><div class="step"><span class="step-number">2</span><div><b>Проверьте наличие сайта</b><p>Карточка 2ГИС + поиск<br>по названию и городу.</p></div></div><div class="step"><span class="step-number">3</span><div><b>Начните разговор</b><p>Сохраните результат проверки<br>и позвоните самостоятельно.</p></div></div></div><div class="aside-divider"></div><a class="aside-link" href="#sources">${icon('external')}Об источниках и доступе</a></section><div class="small-callout">${icon('leaf')}<div><strong>Ваш помощник, ваш темп</strong><p>Контур готовит список.<br>Общение с клиентами остаётся за вами.</p></div></div></aside></div>
    <section class="card results"><header class="card-head"><div class="results-title"><h2>Ваши компании</h2><span class="round-count" id="result-count">0</span></div><div class="result-tools">${button('filters','Фильтры','filter','small')}${button('export-csv','CSV','download','small')}${button('export-xlsx','XLSX','download','small')}</div></header><div class="filters"><input class="filter-input" name="q" data-filter="q" value="${e(filters.q)}" placeholder="Поиск по названию, адресу, телефону" aria-label="Поиск по компаниям"><select class="filter-select" data-filter="website_status" aria-label="Статус проверки сайта"><option value="">Любой статус сайта</option>${Object.entries(state.site_statuses).map(([k,v])=>`<option value="${k}" ${selected(filters.website_status,k)}>${e(v)}</option>`).join('')}</select><select class="filter-select" data-filter="sort" aria-label="Сортировка"><option value="priority" ${selected(filters.sort,'priority')}>Сначала для звонка</option><option value="recent" ${selected(filters.sort,'recent')}>Недавно изменённые</option><option value="name" ${selected(filters.sort,'name')}>По названию</option></select>${moreFilters?moreFilterFields():''}</div><div id="results-body"></div><footer class="card-foot"><span>${icon('info')} Приоритет: публичный телефон + сайт не найден после проверки. Это не оценка бизнеса.</span><span id="filter-summary"></span></footer></section>`;
}
function moreFilterFields(){return `<div class="more-filters"><select class="filter-select" data-filter="lead_status" aria-label="Статус лида"><option value="">Все статусы лида</option>${state.statuses.map(s=>`<option ${selected(filters.lead_status,s)}>${e(s)}</option>`).join('')}</select><select class="filter-select" data-filter="review_status" aria-label="Проверенность"><option value="">Все отметки</option><option value="unreviewed" ${selected(filters.review_status,'unreviewed')}>Не проверены</option><option value="verified" ${selected(filters.review_status,'verified')}>Проверены</option><option value="unsuitable" ${selected(filters.review_status,'unsuitable')}>Неподходящие</option></select><input class="filter-input" data-filter="city" placeholder="Город" aria-label="Фильтр по городу" value="${e(filters.city)}"><input class="filter-input" data-filter="category" placeholder="Категория" aria-label="Фильтр по категории" value="${e(filters.category)}"><label class="check"><input type="checkbox" data-filter="phone" ${checked(filters.phone)}>С телефоном</label><label class="check"><input type="checkbox" data-filter="exclude_chains" ${checked(filters.exclude_chains)}>Без крупных сетей</label>${button('clear-filters','Сбросить','','ghost small')}</div>`;}
function filtered(){
  const normalize=s=>String(s||'').toLowerCase().replaceAll('ё','е').replace(/[^\p{L}\p{N}]/gu,'');
  const list=state.leads.filter(l=>(!filters.q||[l.name,l.city,l.category,l.address,l.phone,l.notes].join(' ').toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.website_status||l.website_status===filters.website_status)&&(!filters.lead_status||l.lead_status===filters.lead_status)&&(!filters.review_status||l.review_status===filters.review_status)&&(!filters.city||normalize(l.city)===normalize(filters.city))&&(!filters.category||l.category.toLowerCase().includes(filters.category.toLowerCase()))&&(!filters.phone||l.phone)&&(!filters.exclude_chains||!l.chain));
  const priority=l=>l.review_status==='unsuitable'?0:l.phone&&l.website_status==='not_found'?3:l.phone&&l.website_status==='manual'?2:1;
  return list.sort((a,b)=>filters.sort==='name'?a.name.localeCompare(b.name,'ru'):filters.sort==='recent'?b.updated_at.localeCompare(a.updated_at):priority(b)-priority(a)||b.updated_at.localeCompare(a.updated_at));
}
function renderResults(){
  if(!byId('results-body'))return;const list=filtered();byId('result-count').textContent=list.length;byId('filter-summary').textContent=`Показано ${list.length} из ${state.leads.length}`;
  if(state.leads.some(l=>l.origin==='2gis_api')){const attribution=document.createElement('a');attribution.href='https://dev.2gis.ru/';attribution.target='_blank';attribution.rel='noopener noreferrer';attribution.textContent='2ГИС';byId('filter-summary').append(' · Данные: ',attribution);}
  const tableHead='<div class="table-scroll"><table><thead><tr><th>Компания / категория</th><th>Адрес</th><th>Сайт</th><th>Контакт</th><th>Статус лида</th><th>Проверка</th><th></th></tr></thead>';
  if(list.length){byId('results-body').innerHTML=tableHead+`<tbody>${list.map(l=>`<tr class="row"><td><button class="company-name" data-action="lead-edit" data-id="${e(l.id)}">${e(l.name)}</button><div class="cell-sub">${e(l.category||'Категория не указана')}${l.chain?' · сеть':''}${l.category_uncertain?' · уточнить категорию':''}</div></td><td>${e(l.address||'Адрес не указан')}<div class="cell-sub">${e(l.city)}</div></td><td><span class="site-tag ${l.website_status}">${e(state.site_statuses[l.website_status])}</span></td><td>${l.phone?e(l.phone):'<span class="cell-sub">Не указан</span>'}</td><td>${tag(l.lead_status,l.lead_status==='Готов к звонку'?'':'neutral')}</td><td>${l.review_status==='unsuitable'?tag('Не подходит','red'):l.review_status==='verified'?tag('Проверено'):tag('Не проверено','warn')}<div class="cell-sub">${l.checked_at?dateOnly(l.checked_at):'Дата не внесена'}</div></td><td>${l.card_url?external(l.card_url,icon('external'),'icon-btn'):''}</td></tr>`).join('')}</tbody></table></div>`;
  }else byId('results-body').innerHTML=tableHead+'</table></div>'+`<div class="empty"><div class="empty-visual" aria-hidden="true"><div class="radar-circle"></div><div class="mini-building">${icon('building')}</div><div class="map-pin"></div><div class="map-pin second"></div></div><div class="empty-text"><h3>${state.leads.length?'По этим фильтрам компаний нет':'Здесь начинается ваш список'}</h3><p>${state.leads.length?'Измените условия или сбросьте фильтры, чтобы увидеть остальные компании.':'Подготовьте поиск выше или добавьте первую компанию вручную. Только реальные данные — с источниками и датой проверки.'}</p><div class="empty-actions">${state.leads.length?button('clear-filters','Сбросить фильтры','filter','small'):button('lead-new','Добавить компанию','plus','small')}${!state.leads.length?button('import','Импорт из файла','upload','ghost small'):''}</div></div></div>`;
}
function agentCard(a){
  const runs=state.runs.filter(r=>r.agent_id===a.id),running=runs.find(r=>r.status==='running');
  return `<article class="card agent-card"><div class="agent-top"><div class="square-icon ${a.color}">${icon(a.kind==='leads'?'building':'bot')}</div>${tag(a.paused?'Приостановлен':running?'Выполняется':a.mode==='ai'&&!state.config.ai_ready?'Нужна модель':'Готов к запуску',a.paused?'neutral':running?'blue':a.mode==='ai'&&!state.config.ai_ready?'warn':'')}</div><h3>${e(a.name)}</h3><p>${e(a.goal)}</p><div class="agent-meta">${tag(a.kind==='leads'?'2ГИС · помощник':a.mode==='ai'?'ИИ-агент':'Без ИИ','neutral')}${tag(`${a.sources.length} ист. · ${a.file_ids.length} файл.`,'neutral')}</div><p class="agent-history">Запусков: ${runs.length}${runs[0]?' · '+dateOnly(runs[0].started_at):' · история пока пуста'}</p><div class="actions">${button('agent-run',running?'Результат':'Запустить',running?'clock':'play','small soft',`data-id="${e(a.id)}" ${a.paused?'disabled':''}`)}<div>${tiny('agent-edit','Настроить агента','edit',a.id)}${tiny('agent-copy','Копировать агента','copy',a.id)}${tiny(a.paused?'agent-resume':'agent-pause',a.paused?'Возобновить':'Приостановить',a.paused?'play':'pause',a.id)}${tiny('agent-history','История агента','clock',a.id)}${a.id!=='company-finder'?tiny('agent-delete','Удалить агента','trash',a.id):''}</div></div></article>`;
}
function agentsPage(){return heading('ВАША КОМАНДА ДЛЯ ПОВСЕДНЕВНЫХ ЗАДАЧ','Агенты, которые работают по вашим правилам.','Настройте задачу, выберите материалы и запустите агента вручную.',button('agent-new','Создать агента','plus','primary'))+`<div class="notice info">${icon('shield')}<span>Каждый агент видит только явно подключённые источники. История и выбранные файлы у каждого свои.</span></div><div class="agents-grid">${state.agents.map(agentCard).join('')}<button class="create-card" data-action="agent-new">${icon('plus')}<b>Ваш следующий агент</b><span>Опишите задачу своими словами или начните с шаблона</span></button></div><h2 class="section-title">Не начинайте с чистого листа</h2><div class="agents-grid">${state.templates.slice(0,3).map(templateCard).join('')}</div>`;}
function templateCard(t){return `<article class="template-card"><div class="square-icon ${t.color}">${icon(t.id==='compare'?'layers':t.id==='files'?'file':t.id==='report'?'list':'spark')}</div><h3>${e(t.name)}</h3><p>${e(t.goal)}</p><div class="actions">${button('template-use','Создать агента','plus','small soft',`data-id="${e(t.id)}"`)}${button('template-edit','Изменить','edit','small ghost',`data-id="${e(t.id)}"`)}</div></article>`;}
function templatesPage(){return heading('ПОЛЕЗНЫЕ ТОЧКИ ОТСЧЁТА','Не повторяйте настройки. Сохраните шаблон.','Меняйте инструкции готовых шаблонов или сохраняйте собственных агентов как шаблоны.',button('template-new','Новый шаблон','plus','primary'))+`<div class="agents-grid">${state.templates.map(templateCard).join('')}</div>`;}
const statusLabel={running:'Выполняется',completed:'Завершён',failed:'Ошибка',paused:'Приостановлен'};
function runRow(r){return `<div class="run-row"><div class="square-icon ${r.status==='failed'?'orange':''}">${icon(r.status==='running'?'clock':r.status==='completed'?'check':'pause')}</div><div class="run-info"><strong>${e(r.agent_name)}</strong><p>${date(r.started_at)}${r.finished_at?' · '+Math.max(0,Math.round((new Date(r.finished_at)-new Date(r.started_at))/1000))+' сек.':''}</p></div>${tag(statusLabel[r.status],{running:'blue',failed:'red',paused:'neutral',completed:''}[r.status])}${button('run-view','Открыть','arrow','small',`data-id="${e(r.id)}"`)}${r.status==='running'?tiny('run-pause','Приостановить запуск','pause',r.id):''}</div>`;}
function runsPage(agentId=''){const runs=state.runs.filter(r=>!agentId||r.agent_id===agentId);return heading('ПРОЗРАЧНАЯ РАБОТА','У каждого результата есть история.','Исходные материалы, настройки на момент запуска и результат сохраняются локально.')+`<section class="runs-list">${runs.length?runs.map(runRow).join(''):`<div class="card empty-page"><div class="square-icon">${icon('clock')}</div><h3>Первый запуск ещё впереди</h3><p>Подготовьте поиск компаний или запустите своего агента. Здесь будет виден каждый шаг и результат.</p><a class="btn soft" href="#agents">${icon('bot')}К моим агентам</a></div>`}</section>`;}
function sourcesPage(){const c=state.config;return heading('ТОЛЬКО ПОДКЛЮЧЁННЫЕ МАТЕРИАЛЫ','Знайте, откуда берутся ответы.','Добавляйте разрешённые данные и отдельно выбирайте, каким агентам они доступны.',button('file-upload','Добавить файл','upload','primary'))+`<div class="source-grid"><article class="card source-card"><div><div class="square-icon">${icon('building')}</div>${tag(c.dgis_ready?'Настроен':'Ручной режим',c.dgis_ready?'':'warn')}</div><h2>Справочник 2ГИС</h2><p>Ручной помощник открывает поисковые запросы. Автоматический поиск использует официальный Places API и требует отдельного права на хранение базы.</p><ul><li>Ключ API: ${c.dgis_key?'настроен':'не задан'}</li><li>Разрешение на хранение: ${c.dgis_license?'подтверждено в окружении':'не подтверждено'}</li><li>Контакты: ${c.dgis_contacts?'запрос поля включён':'нужен отдельный доступ'}</li></ul>${external('https://docs.2gis.com/ru/api/search/places/overview','Документация 2ГИС '+icon('external'),'btn small')}${external('https://law.2gis.ru/webapi-offer/','Условия API','btn ghost small')}</article><article class="card source-card"><div><div class="square-icon blue">${icon('bot')}</div>${tag(c.ai_ready?'Настроена':'Не подключена',c.ai_ready?'':'neutral')}</div><h2>Модель для ваших агентов</h2><p>${c.ai_ready?`Модель: ${e(c.ai_model)}. ${c.ai_remote?'Выбранные материалы отправляются настроенному удалённому серверу.':'Модель работает через локальный сервер.'}`:'Подключите локальную модель Ollama или совместимый сервер. Пока доступен сбор материалов без ИИ.'} Модель не получает инструментов и не открывает ссылки.</p><ul><li>Входной текст — только по разрешению</li><li>Файлы — только явно выбранные</li><li>История — только собственные запуски агента</li></ul><a class="btn small" href="#settings">${icon('settings')}Настроить подключение</a></article></div><section class="card files"><header class="card-head"><div class="card-title"><div class="square-icon orange">${icon('file')}</div><div><h2>Библиотека файлов</h2><p>TXT, MD, CSV, JSON · UTF-8 · до 500 КБ</p></div></div>${tag(state.files.length+' файлов','neutral')}</header>${state.files.length?state.files.map(f=>`<div class="file-row"><div class="square-icon">${icon('file')}</div><div><strong>${e(f.name)}</strong><small>${Math.ceil(f.bytes/1024)} КБ · добавлен ${date(f.created_at)}</small></div></div>`).join(''):`<div class="empty-page"><h3>Материалы для ваших агентов</h3><p>Загрузите файл, затем подключите его в настройках конкретного агента. Файлы с компьютера не читаются автоматически.</p>${button('file-upload','Выбрать файл','upload','small soft')}</div>`}<footer class="card-foot">Секреты и ключи не загружайте. PDF, DOCX и XLSX сначала сохраните как текст или CSV.</footer></section>`;}
function settingsPage(){const c=state.config;return heading('ПРОСТОЕ ЛОКАЛЬНОЕ ПОДКЛЮЧЕНИЕ','Настройте источники один раз.','Секреты задаются через .env. После изменения файла перезапустите приложение.')+`<div class="settings-layout"><div><section class="card settings-card"><h2>Автоматический поиск 2ГИС</h2><p>Настройте официальный ключ Places API. Для вашей базы лидов договор должен разрешать хранение, обработку и экспорт данных: стандартная оферта API этого права не даёт.</p><div class="key-values"><span>API-ключ</span><b>${c.dgis_key?'Задан · скрыт':'Не задан'}</b><span>Разрешение на хранение базы</span><b>${c.dgis_license?'Подтверждено':'Не подтверждено'}</b><span>Запрос контактных данных</span><b>${c.dgis_contacts?'Включён':'Выключен'}</b></div><pre>DGIS_API_KEY=ваш_ключ\nDGIS_STORAGE_LICENSE_CONFIRMED=false\nDGIS_CONTACTS_ENABLED=false</pre><p>Поставьте <code>true</code> для лицензии только после согласования соответствующих прав с 2ГИС. Для контактов нужен доступ к <code>items.contact_groups</code>. Без него телефоны и сайты могут отсутствовать в ответах.</p>${external('https://law.2gis.ru/webapi-offer/','Оферта 2ГИС, пункт 3.1 '+icon('external'),'btn small')}${external('https://docs.2gis.com/ru/api/search/places/overview','Получить ключ и проверить поля','btn small ghost')}</section><section class="card settings-card"><h2>ИИ-модель</h2><p>Для полностью локальной работы используйте Ollama. Укажите имя модели, которую уже загрузили. Все агенты используют это подключение, но имеют отдельные инструкции, разрешения и историю.</p><pre>AI_PROVIDER=ollama\nAI_BASE_URL=http://127.0.0.1:11434\nAI_MODEL=имя_установленной_модели\nAI_ALLOW_REMOTE=false</pre><div class="key-values"><span>Провайдер</span><b>${e(c.ai_provider)}</b><span>Модель</span><b>${e(c.ai_model||'Не выбрана')}</b><span>Сервер</span><b>${e(c.ai_host||'Не настроен')}</b></div>${button('model-check','Проверить подключение','link','small soft',c.ai_ready?'':'disabled')}<p class="connection-line">${icon('info')}Проверка отправит модели короткую тестовую фразу.</p><details class="details-block"><summary>Совместимый удалённый сервер</summary><pre>AI_PROVIDER=compatible\nAI_BASE_URL=https://ваш-сервер.example/v1\nAI_MODEL=имя_модели\nAI_API_KEY=ваш_ключ\nAI_ALLOW_REMOTE=true</pre><p>При AI_ALLOW_REMOTE=true выбранные входные данные, файлы, собственная история и база компаний (если разрешены агенту) передаются этому серверу. При выключенном разрешении удалённые запросы блокируются. Используйте HTTPS.</p></details></section><section class="card settings-card"><h2>Хранение и резервная копия</h2><p>База находится в <code>data/kontur.sqlite</code> в папке приложения. Чтобы сделать полную резервную копию, остановите приложение и скопируйте папку <code>data</code>. Экспорт CSV/XLSX сохраняет выбранные компании, а не настройки агентов.</p></section></div><aside><section class="aside-card"><div class="square-icon">${icon('lock')}</div><h3>Ключи остаются на сервере</h3><p>Интерфейс показывает только факт настройки. Значения ключей не возвращаются в браузер и не включаются в историю запусков.</p><div class="aside-divider"></div><p>Установка пакетов не нужна.<br>Достаточно Node.js 24+<br>и файла Start.cmd.</p></section></aside></div>`;}

function openModal(title,subtitle,body,footer=''){
  modal.innerHTML=`<header class="modal-head"><div><h2 id="modal-title">${e(title)}</h2>${subtitle?`<p>${e(subtitle)}</p>`:''}</div>${tiny('modal-close','Закрыть','close')}</header>${body}${footer?`<footer class="modal-foot">${footer}</footer>`:''}`;
  if(!modal.open)modal.showModal();modal.scrollTop=0;
}
function closeModal(){const wasResult=modalType==='result';modal.close();modalType='';activeRunId=null;if(wasResult){if(route==='companies')getSearchDraft();render();}}
function field(label,name,value='',options={}){const type=options.type||'text';return `<div class="field ${options.full?'full':''}"><label for="f-${name}">${label}</label>${options.textarea?`<textarea id="f-${name}" name="${name}" ${options.required?'required':''} maxlength="${options.max||10000}" ${options.rows?`rows="${options.rows}"`:''} placeholder="${e(options.placeholder||'')}">${e(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${options.required?'required':''} maxlength="${options.max||2000}" placeholder="${e(options.placeholder||'')}">`}${options.hint?`<small>${options.hint}</small>`:''}</div>`;}
function localDateTime(iso){if(!iso)return '';const d=new Date(iso);const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;}
function openLead(id){
  const l=id?state.leads.find(l=>l.id===id):{};if(!l)return;currentEditor={type:'lead',id};modalType='lead';
  const searchUrl='https://yandex.ru/search/?text='+encodeURIComponent([l.name||'',l.city||'', 'официальный сайт'].join(' '));
  const body=`<form id="lead-form"><div class="modal-body"><div class="error-box" id="form-error"></div><p class="form-intro">Вносите сведения, которые вправе хранить и использовать. Публичный телефон должен быть рабочим контактом компании.</p><div class="form-grid">${field('Название компании','name',l.name,{required:true,max:300})}${field('Категория','category',l.category,{max:300})}${field('Город','city',l.city||searchDraft.city,{max:200})}${field('Район','district',l.district,{max:200})}${field('Адрес','address',l.address,{max:500})}${field('Публичный телефон','phone',l.phone,{type:'tel',max:100})}${field('Карточка 2ГИС','card_url',l.card_url,{type:'url',placeholder:'https://2gis.ru/…/firm/…'})}${field('Найденный сайт или кандидат','website',l.website,{type:'url',placeholder:'https://…'})}${field('Краткое описание','description',l.description,{full:true,textarea:true,max:2000})}</div><h3 class="form-section">${icon('shield')} Проверка сайта и источники</h3><div class="notice info">${icon('info')}<span>«Сайт не найден при проверке» требует проверки карточки и независимого поиска по названию с городом. Соцсеть или каталог оставляйте на ручную проверку.</span></div><div class="empty-actions" id="lead-helper-links">${l.card_url?external(l.card_url,'Карточка 2ГИС '+icon('external'),'btn small'):''}${external(searchUrl,'Поиск названия и города '+icon('external'),'btn small')}</div><div class="form-grid" style="margin-top:17px"><div class="field"><label for="f-website_status">Результат проверки сайта</label><select name="website_status" id="f-website_status">${Object.entries(state.site_statuses).map(([k,v])=>`<option value="${k}" ${selected(l.website_status||'manual',k)}>${e(v)}</option>`).join('')}</select></div>${field('Дата фактической проверки','checked_at',localDateTime(l.checked_at),{type:'datetime-local',hint:'Дата импорта не считается датой проверки.'})}${field('Источники — полные ссылки, по одной в строке','sources',(l.sources||[]).join('\n'),{full:true,textarea:true,placeholder:'Ссылка на карточку, независимый поиск и другие проверенные источники',hint:'Ссылка на карточку 2ГИС добавится к источникам автоматически.'})}${field('Где проверяли и что установили','reason',l.reason,{full:true,textarea:true,max:4000,placeholder:'Что указано в карточке? Какой запрос проверяли? Почему результат однозначен или нет?'})}</div><div class="checkbox-grid" style="margin-top:15px"><label class="check"><input name="card_checked" type="checkbox" ${checked(l.card_checked)}>Проверил(а) сайт в карточке 2ГИС</label><label class="check"><input name="web_checked" type="checkbox" ${checked(l.web_checked)}>Проверил(а) поиск названия вместе с городом</label><label class="check"><input name="official_confirmed" type="checkbox" ${checked(l.official_confirmed)}>Подтверждаю принадлежность сайта компании</label><label class="check"><input name="record_now" type="checkbox">Записать текущую дату проверки</label></div><h3 class="form-section">${icon('phone')} Следующий шаг</h3><div class="form-grid"><div class="field"><label for="f-lead_status">Статус лида</label><select name="lead_status" id="f-lead_status">${state.statuses.map(s=>`<option ${selected(l.lead_status||'Новый',s)}>${s}</option>`).join('')}</select></div><div class="field"><label for="f-review_status">Отметка результата</label><select name="review_status" id="f-review_status"><option value="unreviewed" ${selected(l.review_status||'unreviewed','unreviewed')}>Не проверен</option><option value="verified" ${selected(l.review_status,'verified')}>Проверен</option><option value="unsuitable" ${selected(l.review_status,'unsuitable')}>Неподходящий</option></select></div>${field('Ваши заметки','notes',l.notes,{full:true,textarea:true})}</div><div class="checkbox-grid" style="margin-top:15px"><label class="check"><input name="chain" type="checkbox" ${checked(l.chain)}>Крупная сеть</label><label class="check"><input name="category_uncertain" type="checkbox" ${checked(l.category_uncertain)}>Категория требует уточнения</label></div><div style="margin-top:12px">${field('Основание отметки о сети','chain_reason',l.chain_reason,{placeholder:'Например, число филиалов из источника'})}</div>${l.verification_history?.length?`<details class="details-block"><summary>История проверок (${l.verification_history.length})</summary>${[...l.verification_history].reverse().map(h=>`<div class="history-entry"><b>${date(h.checked_at)} · ${e(state.site_statuses[h.website_status])}</b><p>${e(h.reason)}</p>${h.sources.map(s=>external(s,e(s))).join('<br>')}</div>`).join('')}</details>`:''}</div><footer class="modal-foot"><span class="hint">${l.observed_at?'Добавлено: '+date(l.observed_at):'После сохранения компания появится в вашей базе'}</span><div>${button('modal-close','Отмена','','ghost')}<button class="btn primary" type="submit">${icon('check')}Сохранить компанию</button></div></footer></form>`;
  openModal(id?'Карточка компании':'Новая компания','Реальные сведения, источники и понятный результат проверки',body);
}
function readForm(form){const data=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type="checkbox"]').forEach(x=>data[x.name]=x.checked);return data;}
async function saveLead(form){const d=readForm(form);d.sources=d.sources.split('\n').map(s=>s.trim()).filter(Boolean);d.checked_at=d.record_now?new Date().toISOString():d.checked_at?new Date(d.checked_at).toISOString():null;delete d.record_now;
  const out=await api('/api/leads'+(currentEditor.id?'/'+currentEditor.id:''),currentEditor.id?'PUT':'POST',d);closeModal();await refresh();toast(out.duplicate?'Такая компания уже есть. Существующая карточка сохранена без изменений.':'Компания сохранена.');if(out.duplicate)openLead(out.lead.id);
}
function openImport(){modalType='import';openModal('Импорт компаний','CSV с разделителем ; или , либо массив JSON в UTF-8',`<form id="import-form"><div class="modal-body"><div id="form-error" class="error-box"></div><p class="form-intro">Обязательны название и источник. Источник — колонка <code>sources</code> (несколько ссылок разделяйте |) или <code>card_url</code>. Телефон, сайт и адрес можно добавить позже.</p><div class="notice">${icon('info')}<span>Импорт не проверяет сайт. Без подтверждающих данных запись останется со статусом «Нужно проверить вручную». Дубликаты пропускаются, ваши заметки не заменяются.</span></div><div class="field"><label for="import-file">Файл до 1 МБ, максимум 1000 компаний</label><input id="import-file" name="file" type="file" accept=".csv,.json,text/csv,application/json" required></div><p class="hint">Колонки: name, category, city, district, address, phone, card_url, website, sources, notes. Допускаются русские названия основных колонок.</p><a class="btn small" href="/api/import-template">${icon('download')}Скачать пустой шаблон CSV</a><label class="check" style="margin-top:20px"><input name="rights_confirmed" type="checkbox" required>У меня есть право хранить и использовать импортируемые данные</label><div id="import-summary" class="result-meta"></div></div><footer class="modal-foot"><span class="hint">Ошибки показываются отдельно для каждой строки</span><div>${button('modal-close','Закрыть','','ghost')}<button class="btn primary" type="submit">${icon('upload')}Импортировать</button></div></footer></form>`);}
async function readTextFile(file,max=500000){if(!file||file.size>max)throw Error(`Выберите текстовый файл до ${Math.round(max/1000)} КБ.`);try{return new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());}catch{throw Error('Файл должен быть в UTF-8. Пересохраните его с этой кодировкой.');}}
function openFileUpload(){modalType='file';openModal('Материал для агентов','Файл останется локально и не подключится к агентам автоматически',`<form id="file-form"><div class="modal-body"><div id="form-error" class="error-box"></div><div class="field"><label for="material-file">TXT, MD, CSV или JSON · UTF-8 · до 500 КБ</label><input id="material-file" type="file" accept=".txt,.md,.csv,.json" required></div><p class="hint">После загрузки выберите файл в настройках конкретного агента и разрешите чтение файлов. Не загружайте пароли, токены и ключи API.</p></div><footer class="modal-foot"><span></span><div>${button('modal-close','Отмена','','ghost')}<button type="submit" class="btn primary">${icon('upload')}Добавить в библиотеку</button></div></footer></form>`);}

const sourcePairs=[['input','read_input','Данные запуска','Текст, который вы введёте перед запуском'],['files','read_files','Выбранные файлы','Только отмеченные ниже файлы из библиотеки'],['history','read_history','Собственная история','До трёх последних результатов этого агента'],['leads','read_leads','База компаний','До 100 компаний из локальной базы, включая рабочие контакты']];
function openAgent(id,{template=null,editTemplate=false,newTemplate=false}={}){
  let a=id?state.agents.find(a=>a.id===id):template||{name:'',goal:'',instructions:'Работай только с предоставленными материалами. Подтверждай выводы ссылками [S1], [S2]. Отмечай предположения и недостаток данных.',expected_result:'Структурированный ответ с источниками и ограничениями.',input_hint:'Введите исходные данные и задачу.',mode:'ai',output_format:'markdown',sources:['input'],tools:['read_input','create_report','use_model'],file_ids:[],color:'green'};if(!a)return;
  currentEditor={type:editTemplate||newTemplate?'template':'agent',id:editTemplate?a.id:id||null};modalType='agent';
  const pairs=a.kind==='leads'?[['input','read_input','Данные поиска','Город, район, категории и лимит'],['catalog','catalog_search','Каталог 2ГИС','Помощник или официальный API с разрешённой лицензией']]:sourcePairs;
  openModal(editTemplate?'Изменить шаблон':newTemplate?'Новый шаблон':id?'Настройки агента':'Создать своего агента','Задача, материалы и разрешения задаются отдельно для каждого агента',`<form id="agent-form"><div class="modal-body"><div id="form-error" class="error-box"></div>${!id&&!editTemplate?`<div class="description-builder"><label for="agent-description">Начните с задачи обычным языком</label><div class="description-line"><input id="agent-description" placeholder="Например: сравни предложения по созданию сайта">${button('agent-describe','Заполнить форму','arrow','small soft')}</div><p>Описание станет целью и инструкцией. Источники и разрешения вы выбираете ниже.</p></div>`:''}<div class="form-grid">${field('Название','name',a.name,{required:true,max:120})}<div class="field"><label for="f-color">Цвет агента</label><select id="f-color" name="color">${[['green','Зелёный'],['blue','Голубой'],['orange','Песочный'],['purple','Сиреневый']].map(([v,t])=>`<option value="${v}" ${selected(a.color,v)}>${t}</option>`).join('')}</select></div>${field('Цель','goal',a.goal,{required:true,full:true,textarea:true,max:1500})}${field('Инструкции','instructions',a.instructions,{full:true,textarea:true,rows:5})}${field('Ожидаемый результат','expected_result',a.expected_result,{full:true,textarea:true,max:2000})}${field('Подсказка к входным данным','input_hint',a.input_hint,{full:true,max:1000})}<div class="field"><label for="f-mode">Режим работы</label><select id="f-mode" name="mode" ${a.kind==='leads'?'disabled':''}><option value="ai" ${selected(a.mode,'ai')}>Анализ с ИИ-моделью</option><option value="local" ${selected(a.mode,'local')}>Сбор материалов без ИИ</option></select><small>${a.kind==='leads'?'Поиск компаний работает без ИИ.':state.config.ai_ready?'Подключена модель: '+e(state.config.ai_model):'Для анализа нужна модель. Сбор материалов работает без неё.'}</small></div><div class="field"><label for="f-output_format">Формат результата</label><select id="f-output_format" name="output_format">${[['markdown','Структурированный текст (Markdown)'],['json','JSON'],['text','Обычный текст']].map(([v,t])=>`<option value="${v}" ${selected(a.output_format,v)}>${t}</option>`).join('')}</select></div></div><h3 class="form-section">${icon('database')} Разрешённые источники и чтение</h3><div class="checkbox-grid">${pairs.map(([s,t,title,desc])=>`<label class="check"><input type="checkbox" name="source_${s}" ${checked(a.sources.includes(s)&&a.tools.includes(t))}><span>${title}<br><small class="hint">${desc}</small></span></label>`).join('')}</div>${a.kind!=='leads'?`<h3 class="form-section">${icon('file')} Подключённые файлы</h3>${state.files.length?`<div class="checkbox-grid">${state.files.map(f=>`<label class="check"><input type="checkbox" name="file_${e(f.id)}" ${checked(a.file_ids.includes(f.id))}>${e(f.name)}</label>`).join('')}</div>`:'<p class="hint">В библиотеке пока нет файлов. Их можно добавить в разделе «Источники и файлы».</p>'}`:''}<h3 class="form-section">${icon('shield')} Разрешённые действия</h3><div class="checkbox-grid"><label class="check"><input type="checkbox" name="create_report" ${checked(a.tools.includes('create_report'))}>Создавать локальный результат и историю запуска</label>${a.kind!=='leads'?`<label class="check"><input type="checkbox" name="use_model" ${checked(a.tools.includes('use_model'))}>Передавать разрешённые материалы настроенной модели</label>`:''}</div><p class="hint" style="margin-top:15px">Команды, произвольное чтение диска, звонки, сообщения и публикации недоступны. ${state.config.ai_remote?'Внимание: выбрана удалённая модель; разрешённые данные уйдут настроенному серверу.':''}</p></div><footer class="modal-foot">${id&&!editTemplate?button('agent-template','Сохранить шаблон','layers','small ghost',`data-id="${e(id)}"`):'<span class="hint">Ключи задавайте только в .env</span>'}<div>${button('modal-close','Отмена','','ghost')}<button type="submit" class="btn primary">${icon('check')}${currentEditor.type==='template'?'Сохранить шаблон':id?'Сохранить настройки':'Создать агента'}</button></div></footer></form>`);
}
async function saveAgent(form){const d=readForm(form);const isLead=currentEditor.id&&state.agents.find(a=>a.id===currentEditor.id)?.kind==='leads';const pairs=isLead?[['input','read_input'],['catalog','catalog_search']]:sourcePairs;d.sources=[];d.tools=[];d.file_ids=[];
  for(const [s,t] of pairs)if(d['source_'+s]){d.sources.push(s);d.tools.push(t);}
  for(const f of state.files)if(d['file_'+f.id])d.file_ids.push(f.id);
  if(d.create_report)d.tools.push('create_report');if(d.use_model)d.tools.push('use_model');
  if(isLead)d.mode='local';for(const k of Object.keys(d))if(k.startsWith('source_')||k.startsWith('file_')||['create_report','use_model'].includes(k))delete d[k];
  const bucket=currentEditor.type==='template'?'templates':'agents';await api(`/api/${bucket}${currentEditor.id?'/'+currentEditor.id:''}`,currentEditor.id?'PUT':'POST',d);closeModal();await refresh();toast(bucket==='templates'?'Шаблон сохранён.':'Агент сохранён.');
}
function openAgentRun(id){
  const a=state.agents.find(a=>a.id===id);if(!a)return;const run=state.runs.find(r=>r.agent_id===id&&r.status==='running');if(run)return showRun(run.id);
  if(a.kind==='leads'){
    if(a.id==='company-finder'){closeModal();location.hash='companies';setTimeout(()=>byId('search-city')?.focus(),0);return;}
    currentRunAgent=a;modalType='run-agent';
    openModal('Запустить: '+a.name,'Копия встроенного агента 2ГИС',`<form id="lead-agent-run-form"><div class="modal-body"><div id="form-error" class="error-box"></div><div class="form-grid">${field('Город','city',searchDraft.city,{required:true})}${field('Район','district',searchDraft.district)}${field('Категории через запятую','categories',searchDraft.categories.join(', '),{required:true,full:true})}<div class="field"><label for="copy-limit">Количество</label><select id="copy-limit" name="limit"><option>10</option><option selected>30</option><option>50</option><option>100</option></select></div><div class="field"><label for="copy-mode">Режим</label><select id="copy-mode" name="mode"><option value="manual">Ручной помощник</option><option value="api">Официальный API</option></select></div></div></div><footer class="modal-foot"><span></span><button type="submit" class="btn primary">${icon('play')}Запустить</button></footer></form>`);return;
  }
  currentRunAgent=a;modalType='run-agent';openModal('Запустить: '+a.name,a.goal,`<form id="agent-run-form"><div class="modal-body"><div id="form-error" class="error-box"></div>${a.mode==='ai'&&!state.config.ai_ready?`<div class="notice">${icon('info')}<span>Модель ещё не подключена. Настройте её или измените режим агента на «Сбор материалов без ИИ».</span></div>`:''}${a.mode==='local'?`<div class="notice info">${icon('info')}Сохраняется подборка исходных материалов. Анализ ИИ в этом режиме не выполняется.</div>`:''}${field('Входные данные','input','',{full:true,textarea:true,rows:9,max:20000,placeholder:a.input_hint})}<p class="hint">${e(a.expected_result)}</p><div class="agent-meta">${a.sources.map(s=>tag({input:'Текст запуска',files:'Выбранные файлы: '+a.file_ids.length,history:'Своя история',leads:'База компаний'}[s]||s,'neutral')).join('')}</div>${state.config.ai_remote&&a.mode==='ai'?'<div class="notice">Выбранные материалы будут отправлены настроенному удалённому серверу модели.</div>':''}</div><footer class="modal-foot"><span class="hint">Внешние действия недоступны</span><div>${button('modal-close','Отмена','','ghost')}<button type="submit" class="btn primary">${icon('play')}Запустить агента</button></div></footer></form>`);
}
async function showRun(id,refreshOnly=false){
  const r=await api('/api/runs/'+id);
  if(refreshOnly&&(modalType!=='result'||activeRunId!==id||modal.dataset.runStatus===r.status))return;
  activeRunId=id;modalType='result';modal.dataset.runStatus=r.status;
  const sources=r.sources_snapshot||[];
  openModal(r.agent_name,'Запуск '+date(r.started_at),`<div class="modal-body">${r.status==='running'?`<div class="progress-note"><span class="loader"></span>Агент выполняет задачу. Можно закрыть окно — работа продолжится.</div>`:''}${r.error?`<div class="notice ${r.status==='failed'?'error':''}">${icon('info')}${e(r.error)}</div>`:''}${r.result?.links?.length?r.result.links.map(l=>external(l.url,e(l.query)+icon('external'),'result-link')).join(''):''}${r.result?`<pre class="result-output">${e(r.result.text)}</pre>${r.result.warning?`<p class="result-meta">${e(r.result.warning)}</p>`:''}`:''}<p class="result-meta">${tag(statusLabel[r.status],r.status==='failed'?'red':'neutral')} ${r.finished_at?'Завершение: '+date(r.finished_at):'Начало: '+date(r.started_at)}${r.result?.model?' · Модель: '+e(r.result.model):''}</p><details class="details-block"><summary>Материалы и настройки на момент запуска</summary><p>Инструкции, источники и разрешения сохранены именно для этого запуска. Содержимое ссылок автоматически не загружалось.</p><pre>${e(JSON.stringify({agent:r.agent_snapshot,input:r.input_snapshot},null,2))}</pre>${sources.map(s=>`<details><summary>[${s.id}] ${e(s.title)}${s.truncated?' · сокращено':''}</summary><pre>${e(s.content)}</pre>${s.urls?.map(u=>external(u,e(u))).join('<br>')||''}</details>`).join('')}</details></div>`,`${r.status==='running'?button('run-pause','Приостановить','pause','small',`data-id="${e(r.id)}"`):r.result?button('run-download','Скачать результат','download','small',`data-id="${e(r.id)}"`):'<span></span>'}<div>${button('modal-close','Закрыть','','ghost')}${r.agent_snapshot.kind==='leads'&&r.result?button('run-to-companies','К компаниям','arrow','primary'):''}</div>`);
}
function getSearchDraft(){const f=byId('search-form');if(!f)return;const d=readForm(f);searchDraft={...searchDraft,...d,categories:d.categories.split(',').map(s=>s.trim()).filter(Boolean),queries:d.queries.split(',').map(s=>s.trim()).filter(Boolean),limit:Number(d.limit)};}
function exportFile(format){const p=new URLSearchParams({...filters,format});const a=document.createElement('a');a.href='/api/export?'+p;a.download='';a.click();}
function downloadText(name,text,mime='text/plain;charset=utf-8'){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}

document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id;
  try{
    if(action==='modal-close')return closeModal();
    if(action==='lead-new')return openLead();
    if(action==='lead-edit')return openLead(id);
    if(action==='import')return openImport();
    if(action==='file-upload')return openFileUpload();
    if(action==='agent-new')return openAgent();
    if(action==='agent-edit')return openAgent(id);
    if(action==='agent-run')return openAgentRun(id);
    if(action==='template-new')return openAgent(null,{newTemplate:true});
    if(action==='template-use')return openAgent(null,{template:{...state.templates.find(t=>t.id===id),file_ids:[]}});
    if(action==='template-edit')return openAgent(null,{template:state.templates.find(t=>t.id===id),editTemplate:true});
    if(action==='agent-describe'){
      const text=byId('agent-description').value.trim();if(!text)throw Error('Сначала опишите задачу.');byId('f-name').value=text.split(/[.!?\n]/)[0].slice(0,70);byId('f-goal').value=text.slice(0,1500);byId('f-instructions').value=text+'\n\nРаботай только с подключёнными материалами. Привязывай факты к [S1], [S2]. Не выдумывай данные и явно отмечай предположения. Не открывай ссылки и не выполняй внешние действия.';toast('Описание перенесено в форму. Выберите источники и сохраните агента.');return;
    }
    if(action==='agent-copy'){await api('/api/agents/'+id+'/copy','POST',{});await refresh();toast('Копия создана без файлов и чужой истории.');return;}
    if(['agent-pause','agent-resume'].includes(action)){await api('/api/agents/'+id+'/'+(action==='agent-pause'?'pause':'resume'),'POST',{});await refresh();toast(action==='agent-pause'?'Агент приостановлен, активный запрос отменён.':'Агент готов к новому ручному запуску.');return;}
    if(action==='agent-delete'){
      if(!confirm('Удалить агента из списка? История запусков останется в локальной базе.'))return;
      await api('/api/agents/'+id,'DELETE',{});await refresh();toast('Агент удалён из списка. История сохранена.');return;
    }
    if(action==='agent-template'){const dirty=byId('agent-form');if(dirty){await saveAgent(dirty);}await api('/api/agents/'+id+'/template','POST',{});await refresh();toast('Настройки сохранены как новый шаблон. Файлы и история не перенесены.');return;}
    if(action==='agent-history'){const a=state.agents.find(a=>a.id===id);modalType='history';const runs=state.runs.filter(r=>r.agent_id===id);openModal('История: '+a.name,'Только запуски этого агента',`<div class="modal-body runs-list">${runs.length?runs.map(runRow).join(''):'<p class="form-intro">Этот агент ещё не запускался.</p>'}</div>`,button('modal-close','Закрыть','','ghost'));return;}
    if(action==='search-mode'){getSearchDraft();searchDraft.mode=el.dataset.mode;render();return;}
    if(action==='category-chip'){getSearchDraft();const c=el.dataset.category;searchDraft.categories=searchDraft.categories.includes(c)?searchDraft.categories.filter(x=>x!==c):[...searchDraft.categories,c];render();return;}
    if(action==='filters'){getSearchDraft();moreFilters=!moreFilters;render();return;}
    if(action==='clear-filters'){for(const k in filters)filters[k]=typeof filters[k]==='boolean'?false:k==='sort'?'priority':'';getSearchDraft();render();return;}
    if(action==='export-csv'||action==='export-xlsx'){exportFile(action==='export-csv'?'csv':'xlsx');return;}
    if(action==='run-view')return await showRun(id);
    if(action==='run-pause'){await api('/api/runs/'+id+'/pause','POST',{});await refresh(false);if(modalType==='result')await showRun(id);else render();toast('Запуск приостановлен.');return;}
    if(action==='run-to-companies'){closeModal();location.hash='companies';await refresh();return;}
    if(action==='run-download'){const r=await api('/api/runs/'+id);downloadText('kontur-'+id.slice(0,8)+(r.agent_snapshot.output_format==='json'?'.json':'.md'),r.result?.text||r.error||'');return;}
    if(action==='model-check'){el.disabled=true;el.textContent='Проверяем модель…';try{const r=await api('/api/model/check','POST',{});toast('Модель ответила: '+r.model);}finally{if(el.isConnected){el.disabled=false;el.innerHTML=icon('link')+'Проверить подключение';}}return;}
  }catch(err){const box=modal.open&&byId('form-error');if(box)box.textContent=err.message;else toast(err.message,true);}
});
document.addEventListener('input',event=>{
  const t=event.target;if(t.dataset.filter){filters[t.dataset.filter]=t.type==='checkbox'?t.checked:t.value;renderResults();}
  if(t.closest('#search-form'))getSearchDraft();
  if(t.closest('#lead-form')&&['name','city','card_url'].includes(t.name)){
    const d=readForm(byId('lead-form'));const s='https://yandex.ru/search/?text='+encodeURIComponent([d.name,d.city,'официальный сайт'].join(' '));const card=/^https:\/\/([^/]+\.)?2gis\.(ru|com|kz|kg|uz|ae)\//i.test(d.card_url)?d.card_url:'';
    byId('lead-helper-links').innerHTML=(card?external(card,'Карточка 2ГИС '+icon('external'),'btn small'):'')+external(s,'Поиск названия и города '+icon('external'),'btn small');
  }
});
document.addEventListener('change',event=>{const t=event.target;if(t.dataset.filter){filters[t.dataset.filter]=t.type==='checkbox'?t.checked:t.value;renderResults();}if(t.closest('#search-form'))getSearchDraft();});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target,submit=form.querySelector('[type="submit"]');if(submit?.disabled)return;
  if(submit)submit.disabled=true;const errorBox=byId('form-error');if(errorBox)errorBox.textContent='';
  try{
    if(form.id==='search-form'){getSearchDraft();const run=await api('/api/search','POST',searchDraft);await refresh(false);await showRun(run.id);}
    if(form.id==='lead-form')await saveLead(form);
    if(form.id==='agent-form')await saveAgent(form);
    if(form.id==='file-form'){const file=byId('material-file').files[0];const content=await readTextFile(file);await api('/api/files','POST',{name:file.name,content});closeModal();await refresh();toast('Файл добавлен. Подключите его в настройках нужного агента.');}
    if(form.id==='import-form'){
      const file=byId('import-file').files[0];const text=await readTextFile(file,1000000);const out=await api('/api/leads/import','POST',{text,format:file.name.toLowerCase().endsWith('.json')?'json':'csv',rights_confirmed:form.elements.rights_confirmed.checked});await refresh();byId('import-summary').textContent=`Добавлено: ${out.created}. Дубликатов пропущено: ${out.duplicates}. Ошибок: ${out.errors.length}.`+(out.errors.length?'\n'+out.errors.map(x=>`Строка ${x.row}: ${x.message}`).join('\n'):'');byId('import-summary').style.whiteSpace='pre-wrap';toast(`Импорт завершён. Добавлено: ${out.created}, ошибок: ${out.errors.length}.`,out.errors.length>0);
    }
    if(form.id==='agent-run-form'){const run=await api('/api/agents/'+currentRunAgent.id+'/run','POST',{input:form.elements.input.value});await refresh(false);await showRun(run.id);}
    if(form.id==='lead-agent-run-form'){const d=readForm(form);d.categories=d.categories.split(',').map(s=>s.trim()).filter(Boolean);d.limit=Number(d.limit);d.exclude_chains=true;const run=await api('/api/agents/'+currentRunAgent.id+'/run','POST',d);await refresh(false);await showRun(run.id);}
  }catch(err){const box=modal.open&&byId('form-error');if(box){box.textContent=err.message;box.scrollIntoView({behavior:'smooth',block:'nearest'});}else toast(err.message,true);}
  finally{if(submit?.isConnected)submit.disabled=false;}
});
modal.addEventListener('cancel',()=>{const wasResult=modalType==='result';modalType='';activeRunId=null;if(wasResult)render();});
window.addEventListener('hashchange',()=>{if(modal.open)closeModal();if(route==='companies')getSearchDraft();render();window.scrollTo(0,0);});
setInterval(async()=>{
  if(!state||polling||!state.runs.some(r=>r.status==='running'))return;polling=true;
  try{const old=state.runs.filter(r=>r.status==='running').map(r=>r.id);await refresh(false);if(modalType==='result'&&activeRunId)await showRun(activeRunId,true);else if(!modal.open&&['agents','runs'].includes(route))render();else if(!modal.open&&route==='companies'){renderResults();}
    for(const id of old){const r=state.runs.find(r=>r.id===id);if(r?.status==='completed')toast(r.agent_name+': результат готов.');else if(r?.status==='failed')toast(r.agent_name+': '+r.error,true);}
  }catch(err){toast('Нет связи с приложением. Проверьте, что окно сервера открыто.',true);}finally{polling=false;}
},1800);
try{await refresh(false);if(state.preferences){const {id,links,...prefs}=state.preferences;searchDraft={...searchDraft,...prefs};}shell();render();}catch(err){byId('app').innerHTML=`<div class="initial"><div><h2>Не удалось открыть рабочее пространство</h2><p>${e(err.message)}</p><p>Запустите Start.cmd и обновите страницу.</p></div></div>`;}
